#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int64 n, m, x, y;

bool can(int64 size) {
    int64 availableForN = size - size / x;
    int64 availableForM = size - size / y;

    i128 lcm = static_cast<i128>(x) / std::gcd(x, y) * y;
    int64 unavailableForBoth =
        lcm > size ? 0 : size / static_cast<int64>(lcm);
    int64 availableTotal = size - unavailableForBoth;

    return availableForN >= n &&
           availableForM >= m &&
           availableTotal >= n + m;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m >> x >> y;

    int64 low = 1, high = 1000000000000000000LL;
    while (low < high) {
        int64 mid = low + (high - low) / 2;
        if (can(mid))
            high = mid;
        else
            low = mid + 1;
    }

    cout << low << '\n';
    return 0;
}

